mapper.select:
SELECT voyage_number, carrier_code, carrier_name, ship_name,
       departure_date, arrival_date, origin_unlocode, dest_unlocode, status
FROM voyage v

    AND v.origin_unlocode = #{origin}
    AND v.dest_unlocode = #{destination}
    AND v.departure_date >= #{departureFrom}
    AND v.departure_date <= #{departureTo}

        AND (
            (#{cargoType} = 'GENERAL'
                AND NOT EXISTS (SELECT 1 FROM voyage_accepted_cargo_type t
                                WHERE t.voyage_number = v.voyage_number))
            OR EXISTS (SELECT 1 FROM voyage_accepted_cargo_type t
                       WHERE t.voyage_number = v.voyage_number
                         AND t.cargo_type = #{cargoType})
        )


ORDER BY v.departure_date ASC

SELECT cargo_type
FROM voyage_accepted_cargo_type
WHERE voyage_number = #{voyageNumber}
